import { resolvePdfDocumentVariables } from './variables';

export type PdfTemplatePreflightMode =
  | 'authoring'
  | 'publish'
  | 'production_render'
  | 'batch';

export type PdfTemplatePreflightStatus = 'success' | 'warning' | 'error';

export type PdfTemplatePreflightSeverity = 'info' | 'warning' | 'error';

export type PdfTemplatePreflightSource =
  | 'accessibility'
  | 'assets'
  | 'batch'
  | 'bindings'
  | 'print-shell'
  | 'schema'
  | 'security'
  | 'serializer'
  | 'unsupported';

export type PdfTemplatePreflightDiagnosticCode =
  | 'asset_not_render_safe'
  | 'batch_unsafe_template'
  | 'header_footer_margin_too_small'
  | 'invalid_condition_value'
  | 'invalid_page_settings'
  | 'invalid_summary_calculation'
  | 'invalid_table_column'
  | 'invalid_template'
  | 'invalid_theme'
  | 'invalid_variable_type'
  | 'invalid_variable_value'
  | 'missing_pdf_title'
  | 'missing_asset'
  | 'missing_asset_alt_text'
  | 'missing_condition_source'
  | 'missing_optional_variable'
  | 'missing_required_section'
  | 'missing_required_variable'
  | 'missing_summary_source'
  | 'missing_table_source'
  | 'missing_table_header'
  | 'non_descriptive_link_text'
  | 'non_array_table_source'
  | 'secret_like_template_value'
  | 'skipped_heading_level'
  | 'unknown_formatter'
  | 'unknown_variable'
  | 'unsafe_asset_url'
  | 'unsupported_node'
  | (string & {});

export interface PdfTemplatePreflightDiagnostic {
  readonly code: PdfTemplatePreflightDiagnosticCode;
  readonly severity: PdfTemplatePreflightSeverity;
  readonly source: PdfTemplatePreflightSource;
  readonly message: string;
  readonly path: readonly string[];
  readonly nodeId?: string;
  readonly nodeType?: string;
  readonly suggestedFix?: string;
  readonly details?: Readonly<Record<string, unknown>>;
}

export interface PdfTemplateRequiredSection {
  readonly id: string;
  readonly nodeType: string;
  readonly label?: string;
  readonly suggestedFix?: string;
}

export interface PreflightPdfTemplateInput extends VariableResolverOptions {
  readonly template: unknown;
  readonly dataContext?: VariableDataContext;
  readonly mode?: PdfTemplatePreflightMode;
  readonly requiredSections?: readonly PdfTemplateRequiredSection[];
}

export interface PdfTemplatePreflightSummary {
  readonly diagnosticCount: number;
  readonly errorCount: number;
  readonly infoCount: number;
  readonly mode: PdfTemplatePreflightMode;
  readonly templateId?: string;
  readonly templateName?: string;
  readonly warningCount: number;
}

export interface PreflightPdfTemplateResult {
  readonly ok: boolean;
  readonly status: PdfTemplatePreflightStatus;
  readonly mode: PdfTemplatePreflightMode;
  readonly diagnostics: readonly PdfTemplatePreflightDiagnostic[];
  readonly errors: readonly PdfTemplatePreflightDiagnostic[];
  readonly warnings: readonly PdfTemplatePreflightDiagnostic[];
  readonly info: readonly PdfTemplatePreflightDiagnostic[];
  readonly summary: PdfTemplatePreflightSummary;
}

export interface PreflightPdfDocumentAccessibilityInput {
  readonly assets?: readonly DocumentAssetReference[];
  readonly document: DocumentContentNode;
  readonly metadata?: PdfDocumentMetadataInput;
}

export interface PreflightPdfDocumentAccessibilityResult {
  readonly ok: boolean;
  readonly diagnostics: readonly PdfTemplatePreflightDiagnostic[];
  readonly warnings: readonly PdfTemplatePreflightDiagnostic[];
  readonly guaranteesPdfUaCompliance: false;
}

export type PdfTemplatePreflightResult = PreflightPdfTemplateResult;

const blockingModes: ReadonlySet<PdfTemplatePreflightMode> = new Set([
  'batch',
  'production_render',
  'publish',
]);

const knownNodeTypes: ReadonlySet<string> = new Set([
  'assetImage',
  'blockquote',
  'bulletList',
  'conditionalSection',
  'dataTable',
  'doc',
  'documentPlaceholder',
  'hardBreak',
  'heading',
  'horizontalRule',
  'image',
  'listItem',
  'orderedList',
  'pageBreak',
  'paragraph',
  'repeater',
  'summaryBlock',
  'table',
  'tableCell',
  'tableHeader',
  'tableRow',
  'text',
  'variable',
]);

export function preflightPdfTemplate(
  input: PreflightPdfTemplateInput,
): PreflightPdfTemplateResult {
  const mode = input.mode ?? 'authoring';
  const diagnostics: PdfTemplatePreflightDiagnostic[] =
    findSecretLikeTemplateValues(input.template).map((diagnostic) => ({
      code: diagnostic.code,
      details: {
        reason: diagnostic.reason,
        redactedPreview: diagnostic.redactedPreview,
      },
      message: diagnostic.message,
      path: diagnostic.path,
      severity: diagnostic.severity,
      source: 'security',
      suggestedFix:
        'Move credentials, tokens, API keys, and signed URLs into server-side adapter configuration.',
    }));
  const templateResult = DocumentTemplateV1Schema.safeParse(input.template);

  if (!templateResult.success) {
    diagnostics.push(
      ...templateResult.error.issues.map((issue) => ({
        code: 'invalid_template',
        details: {
          issueCode: issue.code,
        },
        message: issue.message,
        path: issue.path.map(String),
        severity: 'error' as const,
        source: 'schema' as const,
        suggestedFix:
          'Update the structured template JSON so it matches DocumentTemplateV1Schema.',
      })),
    );

    return createResult({
      diagnostics,
      mode,
    });
  }

  const template = templateResult.data;
  const dataContext = input.dataContext ?? {};
  const assetRenderMode = resolveAssetRenderMode(mode);
  const serializedDocument = composePdfDocumentHtml({
    assetReferences: template.assets,
    assetRenderMode,
    dataContext,
    document: template.content,
    placeholderBindings: template.placeholderBindings,
    repeaterBindings: template.repeaterBindings,
    summaryBlockBindings: template.summaryBlockBindings,
    tableBindings: template.tableBindings,
  });
  const printDocument = composePrintDocumentHtml({
    document: serializedDocument,
    pageSettings: template.pageSettings,
    theme: template.theme,
    title: template.name,
  });
  const assetPreflight = preflightPdfDocumentAssets({
    assets: template.assets,
    mode: assetRenderMode,
  });

  diagnostics.push(
    ...collectBatchDiagnostics(template, mode),
    ...collectUnsupportedNodeDiagnostics(template.content),
    ...collectRequiredSectionDiagnostics(
      template,
      input.requiredSections ?? [],
    ),
    ...preflightPdfDocumentAccessibility({
      assets: template.assets,
      document: template.content,
      metadata: {
        ...template.pdfSettings.metadata,
        title: template.pdfSettings.metadata.title ?? template.name,
      },
    }).diagnostics,
    ...collectVariableDefinitionDiagnostics(template),
    ...collectDataBindingDiagnostics(template, dataContext),
    ...collectConditionalRuleDiagnostics(template, dataContext, mode),
    ...collectRepeaterBindingDiagnostics(template, dataContext, mode),
    ...collectTableBindingDiagnostics(template, dataContext, input, mode),
    ...collectSummaryBindingDiagnostics(template, dataContext, mode),
    ...printDocument.warnings.map((warning) =>
      convertRenderWarningToDiagnostic(warning, mode),
    ),
    ...assetPreflight.diagnostics.map(convertAssetDiagnostic),
    ...resolvePdfDocumentVariables({
      context: dataContext,
      currency: input.currency,
      formatters: input.formatters,
      locale: input.locale,
      timeZone: input.timeZone,
      variables: serializedDocument.variables,
    }).diagnostics.map(convertVariableResolutionDiagnostic),
  );

  return createResult({
    diagnostics: dedupeDiagnostics(diagnostics),
    mode,
    template,
  });
}

export function preflightPdfDocumentAccessibility(
  input: PreflightPdfDocumentAccessibilityInput,
): PreflightPdfDocumentAccessibilityResult {
  const metadata = PdfDocumentMetadataSchema.parse(input.metadata ?? {});
  const diagnostics: PdfTemplatePreflightDiagnostic[] = [];

  if (!metadata.title) {
    diagnostics.push({
      code: 'missing_pdf_title',
      message:
        'PDF metadata should include a title. This is an accessibility warning, not a PDF/UA guarantee.',
      path: ['pdfSettings', 'metadata', 'title'],
      severity: 'warning',
      source: 'accessibility',
      suggestedFix:
        'Set an explicit PDF metadata title before publish or production rendering.',
    });
  }

  diagnostics.push(
    ...collectHeadingAccessibilityDiagnostics(input.document),
    ...collectImageAccessibilityDiagnostics(input.document, input.assets ?? []),
    ...collectTableAccessibilityDiagnostics(input.document),
    ...collectLinkAccessibilityDiagnostics(input.document),
  );

  return {
    diagnostics,
    guaranteesPdfUaCompliance: false,
    ok: diagnostics.length === 0,
    warnings: diagnostics,
  };
}

function collectBatchDiagnostics(
  template: DocumentTemplateV1,
  mode: PdfTemplatePreflightMode,
): readonly PdfTemplatePreflightDiagnostic[] {
  if (mode !== 'batch') {
    return [];
  }

  if (
    template.status === 'published' &&
    template.engine === 'asym_pdf_document_builder'
  ) {
    return [];
  }

  return [
    {
      code: 'batch_unsafe_template',
      details: {
        engine: template.engine,
        status: template.status,
      },
      message:
        'Batch preflight requires a published Asym PDF template snapshot.',
      path: ['status'],
      severity: 'error',
      source: 'batch',
      suggestedFix:
        'Publish an immutable native PDF template version before creating batch jobs.',
    },
  ];
}

function collectUnsupportedNodeDiagnostics(
  content: DocumentContentNode,
): readonly PdfTemplatePreflightDiagnostic[] {
  const diagnostics: PdfTemplatePreflightDiagnostic[] = [];

  visitContentNodes(content, [], (node, path) => {
    if (knownNodeTypes.has(node.type)) {
      return;
    }

    diagnostics.push({
      code: 'unsupported_node',
      details: {
        nodeType: node.type,
      },
      message: `Template contains unsupported node "${node.type}".`,
      nodeType: node.type,
      path,
      severity: 'warning',
      source: 'unsupported',
      suggestedFix:
        'Replace this block with a PDF Document Builder supported node before publishing.',
    });
  });

  return diagnostics;
}

function collectRequiredSectionDiagnostics(
  template: DocumentTemplateV1,
  sections: readonly PdfTemplateRequiredSection[],
): readonly PdfTemplatePreflightDiagnostic[] {
  if (sections.length === 0) {
    return [];
  }

  const nodeTypes = new Set<string>();
  visitContentNodes(template.content, [], (node) => {
    nodeTypes.add(node.type);
  });

  return sections
    .filter((section) => !nodeTypes.has(section.nodeType))
    .map((section, index) => ({
      code: 'missing_required_section',
      details: {
        nodeType: section.nodeType,
        sectionId: section.id,
      },
      message: `Template is missing required section "${
        section.label ?? section.id
      }".`,
      path: ['requiredSections', String(index)],
      severity: 'error' as const,
      source: 'bindings' as const,
      suggestedFix:
        section.suggestedFix ??
        `Add a "${section.nodeType}" section before publish or production rendering.`,
    }));
}

function collectHeadingAccessibilityDiagnostics(
  content: DocumentContentNode,
): readonly PdfTemplatePreflightDiagnostic[] {
  const diagnostics: PdfTemplatePreflightDiagnostic[] = [];
  let previousLevel = 0;

  visitContentNodes(content, [], (node, path) => {
    if (node.type !== 'heading') {
      return;
    }

    const level = readHeadingLevel(node);

    if (level === undefined) {
      return;
    }

    if (level > previousLevel + 1) {
      diagnostics.push({
        code: 'skipped_heading_level',
        details: {
          headingLevel: level,
          previousHeadingLevel: previousLevel,
        },
        message:
          'Heading levels should not skip levels. This warning does not guarantee PDF/UA compliance.',
        nodeType: node.type,
        path,
        severity: 'warning',
        source: 'accessibility',
        suggestedFix:
          'Adjust heading levels so the document outline moves one level at a time.',
      });
    }

    previousLevel = level;
  });

  return diagnostics;
}

function collectImageAccessibilityDiagnostics(
  content: DocumentContentNode,
  assets: readonly DocumentAssetReference[],
): readonly PdfTemplatePreflightDiagnostic[] {
  const diagnostics: PdfTemplatePreflightDiagnostic[] = [];

  visitContentNodes(content, [], (node, path) => {
    if (node.type !== 'assetImage' && node.type !== 'image') {
      return;
    }

    const role = readImageRole(node, assets);
    if (!requiresAltTextForRole(role)) {
      return;
    }

    if (hasNonEmptyString(readImageAltText(node, assets))) {
      return;
    }

    diagnostics.push({
      code: 'missing_asset_alt_text',
      details: {
        role,
      },
      message:
        'Meaningful images should include alt text. This warning does not guarantee PDF/UA compliance.',
      nodeType: node.type,
      path,
      severity: 'warning',
      source: 'accessibility',
      suggestedFix:
        'Add concise alt text or mark the asset decorative in a later accessibility policy.',
    });
  });

  return diagnostics;
}

function collectTableAccessibilityDiagnostics(
  content: DocumentContentNode,
): readonly PdfTemplatePreflightDiagnostic[] {
  const diagnostics: PdfTemplatePreflightDiagnostic[] = [];

  visitContentNodes(content, [], (node, path) => {
    if (node.type !== 'table') {
      return;
    }

    if (hasDescendantNodeType(node, 'tableHeader')) {
      return;
    }

    diagnostics.push({
      code: 'missing_table_header',
      message:
        'Tables should include header cells for screen readers. This warning does not guarantee PDF/UA compliance.',
      nodeType: node.type,
      path,
      severity: 'warning',
      source: 'accessibility',
      suggestedFix:
        'Use table header cells for at least the first row of structured tables.',
    });
  });

  return diagnostics;
}

function collectLinkAccessibilityDiagnostics(
  content: DocumentContentNode,
): readonly PdfTemplatePreflightDiagnostic[] {
  const diagnostics: PdfTemplatePreflightDiagnostic[] = [];

  visitContentNodes(content, [], (node, path) => {
    if (node.type !== 'text' || !hasLinkMark(node)) {
      return;
    }

    const linkText = (node.text ?? '').trim();

    if (isDescriptiveLinkText(linkText)) {
      return;
    }

    diagnostics.push({
      code: 'non_descriptive_link_text',
      details: {
        linkText,
      },
      message:
        'Link text should describe its destination. This warning does not guarantee PDF/UA compliance.',
      nodeType: node.type,
      path,
      severity: 'warning',
      source: 'accessibility',
      suggestedFix:
        'Replace generic link text with destination-specific wording.',
    });
  });

  return diagnostics;
}

function collectVariableDefinitionDiagnostics(
  template: DocumentTemplateV1,
): readonly PdfTemplatePreflightDiagnostic[] {
  const diagnostics: PdfTemplatePreflightDiagnostic[] = [];

  for (const [index, variable] of template.variables.entries()) {
    if (!coreVariableRegistry.get(variable.key)) {
      diagnostics.push({
        code: 'unknown_variable',
        details: {
          variableKey: variable.key,
        },
        message: `Template variable "${variable.key}" is not in the shared variable registry.`,
        path: ['variables', String(index), 'key'],
        severity: 'error',
        source: 'bindings',
        suggestedFix:
          'Use a registered variable key or add a schema-owned variable registry entry.',
      });
    }

    diagnostics.push(
      ...collectUnknownFormatterDiagnostics({
        formatter: variable.formatter,
        path: ['variables', String(index), 'formatter'],
        variable,
      }),
    );
  }

  for (const [bindingIndex, binding] of template.tableBindings.entries()) {
    for (const [columnIndex, column] of binding.columns.entries()) {
      diagnostics.push(
        ...collectUnknownFormatterDiagnostics({
          formatter: column.formatter,
          path: [
            'tableBindings',
            String(bindingIndex),
            'columns',
            String(columnIndex),
            'formatter',
          ],
          variable: {
            key: `${binding.id}.${column.key}`,
            label: column.label,
            sampleValue: '',
            sourcePath: column.sourcePath,
          },
        }),
      );
    }
  }

  for (const [index, binding] of template.summaryBlockBindings.entries()) {
    diagnostics.push(
      ...collectUnknownFormatterDiagnostics({
        formatter: binding.formatter,
        path: ['summaryBlockBindings', String(index), 'formatter'],
        variable: {
          key: `summary.${binding.id}`,
          label: binding.title ?? binding.id,
          sampleValue: 0,
        },
      }),
    );
  }

  return diagnostics;
}

function collectUnknownFormatterDiagnostics(input: {
  readonly formatter: string | undefined;
  readonly path: readonly string[];
  readonly variable: Pick<
    VariableDefinition,
    'key' | 'label' | 'sampleValue' | 'sourcePath'
  >;
}): readonly PdfTemplatePreflightDiagnostic[] {
  if (!input.formatter || defaultVariableFormatters[input.formatter]) {
    return [];
  }

  return [
    {
      code: 'unknown_formatter',
      details: {
        formatter: input.formatter,
        sourcePath: input.variable.sourcePath,
        variableKey: input.variable.key,
      },
      message: `Unknown variable formatter "${input.formatter}".`,
      path: input.path,
      severity: 'error',
      source: 'bindings',
      suggestedFix:
        'Use one of the package-supported deterministic formatters.',
    },
  ];
}

function collectDataBindingDiagnostics(
  template: DocumentTemplateV1,
  dataContext: VariableDataContext,
): readonly PdfTemplatePreflightDiagnostic[] {
  const diagnostics: PdfTemplatePreflightDiagnostic[] = [];
  const templateVariableKeys = new Set(
    template.variables.map((variable) => variable.key),
  );

  for (const [index, binding] of template.dataBindings.entries()) {
    if (
      !templateVariableKeys.has(binding.variableKey) &&
      !coreVariableRegistry.get(binding.variableKey)
    ) {
      diagnostics.push({
        code: 'unknown_variable',
        details: {
          bindingId: binding.id,
          variableKey: binding.variableKey,
        },
        message: `Data binding "${binding.id}" references unknown variable "${binding.variableKey}".`,
        path: ['dataBindings', String(index), 'variableKey'],
        severity: 'error',
        source: 'bindings',
        suggestedFix:
          'Point this binding at a registered template variable key.',
      });
    }

    if (!binding.required) {
      continue;
    }

    const lookup = getValueAtDataPath(dataContext, binding.sourcePath);

    if (lookup.found && !isMissingValue(lookup.value)) {
      continue;
    }

    diagnostics.push({
      code: 'missing_required_variable',
      details: {
        bindingId: binding.id,
        sourcePath: binding.sourcePath,
        variableKey: binding.variableKey,
      },
      message: `Required binding "${binding.variableKey}" is missing data at "${binding.sourcePath}".`,
      path: ['dataContext', ...binding.sourcePath.split('.')],
      severity: 'error',
      source: 'bindings',
      suggestedFix:
        'Provide this data path or remove the required binding before publishing.',
    });
  }

  return diagnostics;
}

function collectConditionalRuleDiagnostics(
  template: DocumentTemplateV1,
  dataContext: VariableDataContext,
  mode: PdfTemplatePreflightMode,
): readonly PdfTemplatePreflightDiagnostic[] {
  return template.conditionalRules.flatMap((rule, index) => {
    const result = evaluateConditionalRule({
      context: dataContext,
      rule,
    });

    return result.diagnostics.map((diagnostic) =>
      convertConditionalDiagnostic(rule, index, diagnostic, mode),
    );
  });
}

function collectRepeaterBindingDiagnostics(
  template: DocumentTemplateV1,
  dataContext: VariableDataContext,
  mode: PdfTemplatePreflightMode,
): readonly PdfTemplatePreflightDiagnostic[] {
  return template.repeaterBindings.flatMap((binding, index) => {
    const result = resolveRepeaterItems({
      binding,
      context: dataContext,
    });

    return result.diagnostics.map((diagnostic) =>
      convertRepeaterDiagnostic(index, diagnostic, mode),
    );
  });
}

function collectTableBindingDiagnostics(
  template: DocumentTemplateV1,
  dataContext: VariableDataContext,
  formatterOptions: VariableResolverOptions,
  mode: PdfTemplatePreflightMode,
): readonly PdfTemplatePreflightDiagnostic[] {
  return template.tableBindings.flatMap((binding, index) => {
    const result = resolveTableRows({
      binding,
      context: dataContext,
      currency: formatterOptions.currency,
      locale: formatterOptions.locale,
      timeZone: formatterOptions.timeZone,
    });

    return result.diagnostics.map((diagnostic) =>
      convertTableDiagnostic(index, diagnostic, mode),
    );
  });
}

function collectSummaryBindingDiagnostics(
  template: DocumentTemplateV1,
  dataContext: VariableDataContext,
  mode: PdfTemplatePreflightMode,
): readonly PdfTemplatePreflightDiagnostic[] {
  return template.summaryBlockBindings.flatMap((binding, index) =>
    validateSummaryBinding({
      binding,
      dataContext,
      index,
      mode,
      tableBindings: template.tableBindings,
    }),
  );
}

function validateSummaryBinding(input: {
  readonly binding: SummaryBlockBinding;
  readonly dataContext: VariableDataContext;
  readonly index: number;
  readonly mode: PdfTemplatePreflightMode;
  readonly tableBindings: readonly TableBinding[];
}): readonly PdfTemplatePreflightDiagnostic[] {
  const calculation = input.binding.calculation;
  const path = ['summaryBlockBindings', String(input.index), 'calculation'];
  const diagnostics: readonly CalculationDiagnostic[] =
    calculation.type === 'total_contributions'
      ? calculateNumericAggregate({
          context: input.dataContext,
          operation: 'sum',
          precision: input.binding.precision,
          sourcePath: calculation.sourcePath,
          valuePath: calculation.amountPath,
        }).diagnostics
      : calculation.type === 'invoice_totals'
        ? calculateInvoiceTotals({
            amountPath: calculation.amountPath,
            context: input.dataContext,
            discountPath: calculation.discountPath,
            lineItemsPath: calculation.lineItemsPath,
            precision: input.binding.precision,
            quantityPath: calculation.quantityPath,
            ratePath: calculation.ratePath,
            taxPath: calculation.taxPath,
          }).diagnostics
        : calculation.type === 'financial_report_totals'
          ? calculateFinancialTotals({
              amountPath: calculation.amountPath,
              categoryPath: calculation.categoryPath,
              context: input.dataContext,
              expenseCategories: calculation.expenseCategories,
              incomeCategories: calculation.incomeCategories,
              precision: input.binding.precision,
              sourcePath: calculation.sourcePath,
            }).diagnostics
          : calculation.type === 'grouped_subtotals' ||
              calculation.type === 'grand_total'
            ? calculateGroupedTableTotals({
                context: input.dataContext,
                groupPath: calculation.groupPath,
                precision: input.binding.precision,
                sourcePath: calculation.sourcePath,
                valuePath: calculation.valuePath,
              }).diagnostics
            : validateTableTotalSummary({
                binding: input.binding,
                dataContext: input.dataContext,
                path,
                tableBindings: input.tableBindings,
              });

  return diagnostics.map((diagnostic) =>
    convertCalculationDiagnostic({
      bindingId: input.binding.id,
      diagnostic,
      mode: input.mode,
      path,
    }),
  );
}

function validateTableTotalSummary(input: {
  readonly binding: SummaryBlockBinding;
  readonly dataContext: VariableDataContext;
  readonly path: readonly string[];
  readonly tableBindings: readonly TableBinding[];
}): readonly CalculationDiagnostic[] {
  const calculation = input.binding.calculation;

  if (calculation.type !== 'table_total') {
    return [];
  }

  const tableBinding = input.tableBindings.find(
    (binding) => binding.id === calculation.tableBindingId,
  );

  if (!tableBinding) {
    return [
      {
        code: 'invalid_table_calculation_binding',
        details: {
          tableBindingId: calculation.tableBindingId,
        },
        message: `Summary block references unknown table binding "${calculation.tableBindingId}".`,
        severity: 'error',
      },
    ];
  }

  return calculateTableTotals({
    context: input.dataContext,
    precision: input.binding.precision,
    tableBinding: {
      ...tableBinding,
      totals: [
        {
          columnKey: calculation.columnKey,
          label: calculation.label,
          operation: calculation.operation ?? 'sum',
        },
      ],
    },
  }).diagnostics;
}

function convertConditionalDiagnostic(
  rule: ConditionalRule,
  index: number,
  diagnostic: {
    readonly code: string;
    readonly severity: 'warning' | 'error';
    readonly message: string;
    readonly fieldPath: string;
    readonly operator: ConditionalRule['operator'];
    readonly details?: Readonly<Record<string, unknown>>;
  },
  mode: PdfTemplatePreflightMode,
): PdfTemplatePreflightDiagnostic {
  return {
    code:
      diagnostic.code === 'missing_condition_field'
        ? 'missing_condition_source'
        : 'invalid_condition_value',
    details: {
      fieldPath: diagnostic.fieldPath,
      operator: diagnostic.operator,
      ruleId: rule.id,
      ...diagnostic.details,
    },
    message: diagnostic.message,
    path: ['conditionalRules', String(index)],
    severity: normalizeBindingSeverity(diagnostic.severity, mode),
    source: 'bindings',
    suggestedFix:
      'Update the condition source path or provide sample data that exercises this rule.',
  };
}

function convertRepeaterDiagnostic(
  index: number,
  diagnostic: RepeaterResolutionDiagnostic,
  mode: PdfTemplatePreflightMode,
): PdfTemplatePreflightDiagnostic {
  return {
    code: diagnostic.code,
    details: {
      bindingId: diagnostic.bindingId,
      itemAlias: diagnostic.itemAlias,
      sourceIndex: diagnostic.sourceIndex,
      sourcePath: diagnostic.sourcePath,
      ...diagnostic.details,
    },
    message: diagnostic.message,
    path: ['repeaterBindings', String(index)],
    severity: normalizeBindingSeverity(diagnostic.severity, mode),
    source: 'bindings',
    suggestedFix:
      'Update the repeater source path, filters, or sample data so the source resolves to an array.',
  };
}

function convertTableDiagnostic(
  index: number,
  diagnostic: TableResolutionDiagnostic,
  mode: PdfTemplatePreflightMode,
): PdfTemplatePreflightDiagnostic {
  const code =
    diagnostic.code === 'unsupported_table_column_value'
      ? 'invalid_table_column'
      : diagnostic.code;

  return {
    code,
    details: {
      bindingId: diagnostic.bindingId,
      columnKey: diagnostic.columnKey,
      sourceIndex: diagnostic.sourceIndex,
      sourcePath: diagnostic.sourcePath,
      ...diagnostic.details,
    },
    message: diagnostic.message,
    path: ['tableBindings', String(index)],
    severity: normalizeBindingSeverity(diagnostic.severity, mode),
    source: 'bindings',
    suggestedFix:
      diagnostic.code === 'unsupported_table_column_value'
        ? 'Point the table column at a field available on every resolved row or provide an approved fallback.'
        : 'Update the table source path or sample data so the table source resolves to an array.',
  };
}

function convertCalculationDiagnostic(input: {
  readonly bindingId: string;
  readonly diagnostic: CalculationDiagnostic;
  readonly mode: PdfTemplatePreflightMode;
  readonly path: readonly string[];
}): PdfTemplatePreflightDiagnostic {
  return {
    code: 'invalid_summary_calculation',
    details: {
      bindingId: input.bindingId,
      diagnosticCode: input.diagnostic.code,
      fieldPath: input.diagnostic.fieldPath,
      sourceIndex: input.diagnostic.sourceIndex,
      sourcePath: input.diagnostic.sourcePath,
      ...input.diagnostic.details,
    },
    message: input.diagnostic.message,
    path: input.path,
    severity: normalizeBindingSeverity(input.diagnostic.severity, input.mode),
    source: 'bindings',
    suggestedFix:
      'Update the structured calculation reference so it points at resolved table or data fields.',
  };
}

function convertRenderWarningToDiagnostic(
  warning: PdfDocumentRenderWarning,
  mode: PdfTemplatePreflightMode,
): PdfTemplatePreflightDiagnostic {
  const code = mapRenderWarningCode(warning);
  const source = warning.source ?? resolveRenderWarningSource(warning);

  return {
    code,
    details: warning.details,
    message: warning.message,
    nodeId: readNodeId(warning.details),
    nodeType: warning.nodeType,
    path: warning.path,
    severity: normalizeRenderSeverity(warning, mode),
    source,
    suggestedFix: suggestFixForCode(code),
  };
}

function convertAssetDiagnostic(
  diagnostic: PdfDocumentAssetDiagnostic,
): PdfTemplatePreflightDiagnostic {
  return {
    code: diagnostic.code,
    details: {
      assetId: diagnostic.assetId,
      referenceId: diagnostic.referenceId,
      role: diagnostic.role,
      ...diagnostic.details,
    },
    message: diagnostic.message,
    path: diagnostic.path,
    severity: diagnostic.severity,
    source: 'assets',
    suggestedFix: suggestFixForCode(diagnostic.code),
  };
}

function convertVariableResolutionDiagnostic(
  diagnostic: VariableResolutionDiagnostic,
): PdfTemplatePreflightDiagnostic {
  return {
    code: mapVariableDiagnosticCode(diagnostic),
    details: {
      formatter: diagnostic.formatter,
      sourcePath: diagnostic.sourcePath,
      variableKey: diagnostic.variableKey,
      ...diagnostic.details,
    },
    message: diagnostic.message,
    path: diagnostic.sourcePath
      ? ['dataContext', ...diagnostic.sourcePath.split('.')]
      : ['variables', diagnostic.variableKey],
    severity: diagnostic.severity,
    source: 'bindings',
    suggestedFix: suggestFixForCode(mapVariableDiagnosticCode(diagnostic)),
  };
}

function mapVariableDiagnosticCode(
  diagnostic: VariableResolutionDiagnostic,
): PdfTemplatePreflightDiagnosticCode {
  if (diagnostic.code === 'missing_required_value') {
    return 'missing_required_variable';
  }

  if (diagnostic.code === 'missing_optional_value') {
    return 'missing_optional_variable';
  }

  return diagnostic.code;
}

function mapRenderWarningCode(
  warning: PdfDocumentRenderWarning,
): PdfTemplatePreflightDiagnosticCode {
  if (warning.code === 'unsupported_table_column_value') {
    return 'invalid_table_column';
  }

  if (warning.code === 'invalid_calculation_reference') {
    return warning.details && 'formatter' in warning.details
      ? 'unknown_formatter'
      : 'invalid_summary_calculation';
  }

  if (warning.code === 'missing_table_source') {
    return 'missing_table_source';
  }

  if (warning.code === 'non_array_table_source') {
    return 'non_array_table_source';
  }

  if (warning.code === 'condition_evaluation_warning') {
    return 'missing_condition_source';
  }

  if (warning.code === 'condition_evaluation_error') {
    return 'invalid_condition_value';
  }

  return warning.code;
}

function resolveRenderWarningSource(
  warning: PdfDocumentRenderWarning,
): PdfTemplatePreflightSource {
  if (warning.source === 'print-shell') {
    return 'print-shell';
  }

  return 'serializer';
}

function normalizeRenderSeverity(
  warning: PdfDocumentRenderWarning,
  mode: PdfTemplatePreflightMode,
): PdfTemplatePreflightSeverity {
  if (warning.severity === 'error') {
    return 'error';
  }

  if (!blockingModes.has(mode)) {
    return warning.severity;
  }

  const blockingCodes = new Set([
    'condition_evaluation_error',
    'condition_evaluation_warning',
    'invalid_calculation_reference',
    'invalid_document',
    'invalid_placeholder',
    'invalid_repeater_binding',
    'invalid_summary_block_binding',
    'invalid_table_binding',
    'missing_condition_context',
    'missing_repeater_context',
    'missing_summary_block_context',
    'missing_table_context',
    'missing_table_source',
    'non_array_table_source',
    'unsupported_table_column_value',
    'unsupported_node',
  ]);

  return blockingCodes.has(warning.code) ? 'error' : warning.severity;
}

function normalizeBindingSeverity(
  severity: 'warning' | 'error',
  mode: PdfTemplatePreflightMode,
): PdfTemplatePreflightSeverity {
  if (severity === 'error' || blockingModes.has(mode)) {
    return 'error';
  }

  return severity;
}

function resolveAssetRenderMode(
  mode: PdfTemplatePreflightMode,
): PdfDocumentAssetRenderMode {
  return mode === 'production_render' || mode === 'batch'
    ? 'production_render'
    : 'browser_preview';
}

function createResult(input: {
  readonly mode: PdfTemplatePreflightMode;
  readonly diagnostics: readonly PdfTemplatePreflightDiagnostic[];
  readonly template?: DocumentTemplateV1;
}): PreflightPdfTemplateResult {
  const diagnostics = input.diagnostics;
  const errors = diagnostics.filter(
    (diagnostic) => diagnostic.severity === 'error',
  );
  const warnings = diagnostics.filter(
    (diagnostic) => diagnostic.severity === 'warning',
  );
  const info = diagnostics.filter(
    (diagnostic) => diagnostic.severity === 'info',
  );
  const status: PdfTemplatePreflightStatus =
    errors.length > 0 ? 'error' : warnings.length > 0 ? 'warning' : 'success';

  return {
    diagnostics,
    errors,
    info,
    mode: input.mode,
    ok: errors.length === 0,
    status,
    summary: {
      diagnosticCount: diagnostics.length,
      errorCount: errors.length,
      infoCount: info.length,
      mode: input.mode,
      templateId: input.template?.id,
      templateName: input.template?.name,
      warningCount: warnings.length,
    },
    warnings,
  };
}

function dedupeDiagnostics(
  diagnostics: readonly PdfTemplatePreflightDiagnostic[],
): readonly PdfTemplatePreflightDiagnostic[] {
  const seen = new Set<string>();
  const deduped: PdfTemplatePreflightDiagnostic[] = [];

  for (const diagnostic of diagnostics) {
    const key = JSON.stringify({
      code: diagnostic.code,
      details: diagnostic.details,
      message: diagnostic.message,
      path: diagnostic.path,
      source: diagnostic.source,
    });

    if (seen.has(key)) {
      continue;
    }

    seen.add(key);
    deduped.push(diagnostic);
  }

  return deduped;
}

function visitContentNodes(
  node: DocumentContentNode,
  path: readonly string[],
  visitor: (node: DocumentContentNode, path: readonly string[]) => void,
): void {
  visitor(node, path);

  for (const [index, child] of (node.content ?? []).entries()) {
    visitContentNodes(child, [...path, 'content', String(index)], visitor);
  }
}

function readHeadingLevel(node: DocumentContentNode): number | undefined {
  const level = node.attrs?.level;

  return typeof level === 'number' && Number.isInteger(level)
    ? level
    : undefined;
}

function readImageRole(
  node: DocumentContentNode,
  assets: readonly DocumentAssetReference[],
): string {
  const nestedAsset = readRecord(node.attrs?.asset);
  const referencedAsset = resolveImageAssetReference(node, assets);
  const role =
    readString(node.attrs?.role) ??
    readString(nestedAsset?.role) ??
    referencedAsset?.role;

  return role ?? 'image';
}

function readImageAltText(
  node: DocumentContentNode,
  assets: readonly DocumentAssetReference[],
): string | undefined {
  const nestedAsset = readRecord(node.attrs?.asset);
  const referencedAsset = resolveImageAssetReference(node, assets);

  return (
    readString(node.attrs?.altText) ??
    readString(node.attrs?.alt) ??
    readString(nestedAsset?.altText) ??
    referencedAsset?.altText
  );
}

function resolveImageAssetReference(
  node: DocumentContentNode,
  assets: readonly DocumentAssetReference[],
): DocumentAssetReference | undefined {
  const nestedAsset = readRecord(node.attrs?.asset);
  const referenceId =
    readString(node.attrs?.assetId) ??
    readString(node.attrs?.id) ??
    readString(nestedAsset?.assetId) ??
    readString(nestedAsset?.id);

  if (!referenceId) {
    return undefined;
  }

  return assets.find(
    (asset) => asset.id === referenceId || asset.assetId === referenceId,
  );
}

function requiresAltTextForRole(role: string): boolean {
  return role === 'image' || role === 'logo' || role === 'signature';
}

function hasDescendantNodeType(
  node: DocumentContentNode,
  nodeType: string,
): boolean {
  let found = false;

  visitContentNodes(node, [], (candidate) => {
    if (candidate.type === nodeType) {
      found = true;
    }
  });

  return found;
}

function hasLinkMark(node: DocumentContentNode): boolean {
  return (node.marks ?? []).some((mark) => mark.type === 'link');
}

function isDescriptiveLinkText(value: string): boolean {
  const normalizedValue = value.trim().toLowerCase();

  if (!normalizedValue) {
    return false;
  }

  return !new Set([
    'click here',
    'here',
    'learn more',
    'more',
    'read more',
  ]).has(normalizedValue);
}

function hasNonEmptyString(value: string | undefined): boolean {
  return typeof value === 'string' && value.trim().length > 0;
}

function readString(value: unknown): string | undefined {
  return typeof value === 'string' ? value : undefined;
}

function readRecord(
  value: unknown,
): Readonly<Record<string, unknown>> | undefined {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
    ? (value as Readonly<Record<string, unknown>>)
    : undefined;
}

function readNodeId(
  details: Readonly<Record<string, unknown>> | undefined,
): string | undefined {
  const nodeId = details?.nodeId;

  return typeof nodeId === 'string' ? nodeId : undefined;
}

function suggestFixForCode(
  code: PdfTemplatePreflightDiagnosticCode,
): string | undefined {
  switch (code) {
    case 'asset_not_render_safe':
    case 'missing_asset':
    case 'unsafe_asset_url':
      return 'Resolve the asset through an adapter that provides a DocRaptor-reachable render-safe URL.';
    case 'invalid_table_column':
      return 'Point the table column at a row field that exists in the selected dataset.';
    case 'invalid_summary_calculation':
    case 'missing_summary_source':
      return 'Update the summary calculation reference so it uses structured table or data paths that resolve.';
    case 'missing_condition_source':
      return 'Update the conditional field path or provide sample data for that path.';
    case 'missing_required_variable':
      return 'Provide the required source data before publish or production rendering.';
    case 'unknown_formatter':
      return 'Use one of the schema package deterministic formatter names.';
    case 'unsupported_node':
      return 'Replace the node with a supported PDF Document Builder block.';
    default:
      return undefined;
  }
}

function isMissingValue(value: unknown): boolean {
  return value === undefined || value === null || value === '';
}
